1	package v1
2	
3	import (
4		"bytes"
5		"context"
6		"image"
7	
8		"github.com/disintegration/imaging"
9		"github.com/pkg/errors"
10		"google.golang.org/grpc/codes"
11		"google.golang.org/grpc/status"
12	
13		"github.com/usememos/memos/internal/motionphoto"
14		v1pb "github.com/usememos/memos/proto/gen/api/v1"
15		storepb "github.com/usememos/memos/proto/gen/store"
16	)
17	
18	func validateClientMotionMedia(motion *v1pb.MotionMedia, attachmentUID string) (*storepb.MotionMedia, error) {
19		if motion == nil {
20			return nil, nil
21		}
22	
23		if motion.Family != v1pb.MotionMediaFamily_APPLE_LIVE_PHOTO {
24			return nil, status.Errorf(codes.InvalidArgument, "only Apple Live Photo motion metadata can be provided by clients")
25		}
26		if motion.Role != v1pb.MotionMediaRole_STILL && motion.Role != v1pb.MotionMediaRole_VIDEO {
27			return nil, status.Errorf(codes.InvalidArgument, "invalid Apple Live Photo motion role")
28		}
29	
30		storeMotion := convertMotionMediaToStore(motion)
31		if storeMotion.GroupId == "" {
32			return nil, status.Errorf(codes.InvalidArgument, "motion media group_id is required")
33		}
34		if storeMotion.Family == storepb.MotionMediaFamily_ANDROID_MOTION_PHOTO && storeMotion.GroupId == "" {
35			storeMotion.GroupId = attachmentUID
36		}
37	
38		return storeMotion, nil
39	}
40	
41	func detectAndroidMotionMedia(blob []byte, mimeType, attachmentUID string) *storepb.MotionMedia {
42		if mimeType != "image/jpeg" && mimeType != "image/jpg" {
43			return nil
44		}
45	
46		detection := motionphoto.DetectJPEG(blob)
47		if detection == nil {
48			return nil
49		}
50	
51		return &storepb.MotionMedia{
52			Family:                  storepb.MotionMediaFamily_ANDROID_MOTION_PHOTO,
53			Role:                    storepb.MotionMediaRole_CONTAINER,
54			GroupId:                 attachmentUID,
55			PresentationTimestampUs: detection.PresentationTimestampUs,
56			HasEmbeddedVideo:        true,
57		}
58	}
59	
60	// shouldStripExif checks if the MIME type is an image format that may contain EXIF metadata.
61	// Returns true for formats like JPEG, TIFF, WebP, HEIC, and HEIF which commonly contain
62	// privacy-sensitive metadata such as GPS coordinates, camera settings, and device information.
63	func shouldStripExif(mimeType string) bool {
64		return exifCapableImageTypes[mimeType]
65	}
66	
67	func (s *APIV1Service) acquireImageProcessingSlot(ctx context.Context) (func(), error) {
68		if s.imageProcessingSemaphore == nil {
69			return func() {}, nil
70		}
71		if err := s.imageProcessingSemaphore.Acquire(ctx, 1); err != nil {
72			return nil, err
73		}
74		return func() {
75			s.imageProcessingSemaphore.Release(1)
76		}, nil
77	}
78	
79	func validateImagePixelCount(imageData []byte) error {
80		config, _, err := image.DecodeConfig(bytes.NewReader(imageData))
81		if err != nil {
82			// Some formats supported by imaging do not expose dimensions through
83			// the standard image registry. Let the full decoder handle those.
84			return nil //nolint:nilerr
85		}
86		if config.Width <= 0 || config.Height <= 0 {
87			return errors.New("invalid image dimensions")
88		}
89		if config.Width > maxImagePixels/config.Height {
90			return errors.Errorf("image dimensions exceed maximum of %d pixels", maxImagePixels)
91		}
92		return nil
93	}
94	
95	// stripImageExif removes EXIF metadata from image files by decoding and re-encoding them.
96	// This prevents exposure of sensitive metadata such as GPS location, camera details, and timestamps.
97	//
98	// The function preserves the correct image orientation by applying EXIF orientation tags
99	// during decoding before stripping all metadata. Images are re-encoded with high quality
100	// to minimize visual degradation.
101	//
102	// Supported formats:
103	//   - JPEG/JPG: Re-encoded as JPEG with quality 95
104	//   - PNG: Re-encoded as PNG (lossless)
105	//   - TIFF/WebP/HEIC/HEIF: Re-encoded as JPEG with quality 95
106	//
107	// Returns the cleaned image data without any EXIF metadata, or an error if processing fails.
108	func stripImageExif(imageData []byte, mimeType string) ([]byte, error) {
109		if err := validateImagePixelCount(imageData); err != nil {
110			return nil, err
111		}
112	
113		// Decode image with automatic EXIF orientation correction.
114		// This ensures the image displays correctly after metadata removal.
115		img, err := imaging.Decode(bytes.NewReader(imageData), imaging.AutoOrientation(true))
116		if err != nil {
117			return nil, errors.Wrap(err, "failed to decode image")
118		}
119	
120		// Re-encode the image without EXIF metadata.
121		var buf bytes.Buffer
122		var encodeErr error
123	
124		if mimeType == "image/png" {
125			// Preserve PNG format for lossless encoding
126			encodeErr = imaging.Encode(&buf, img, imaging.PNG)
127		} else {
128			// For JPEG, TIFF, WebP, HEIC, HEIF - re-encode as JPEG.
129			// This ensures EXIF is stripped and provides good compression.
130			encodeErr = imaging.Encode(&buf, img, imaging.JPEG, imaging.JPEGQuality(defaultJPEGQuality))
131		}
132	
133		if encodeErr != nil {
134			return nil, errors.Wrap(encodeErr, "failed to encode image")
135		}
136	
137		return buf.Bytes(), nil
138	}
